%[text] # Validation - Road Grade Profile block
%[text] This script is for the visual inspection of plots and also used by unit test. After changing this script, make sure the tests continue to pass.
model_name = "HarnessModel_RoadGradeProfile_CustomComponent";
block_path = model_name + "/Road Grade Profile";
load_system(model_name)

sg = @bevutil1.CodeUtil.stringify;

sim_in = Simulink.SimulationInput(model_name);
%[text] Validation setup. Use "ft" for the unit of length. 10,000 second run at 1 ft/s speed yields 10,000 ft in the curvilinear travel distance at the end of simulation.
sim_in = setModelParameter(sim_in, StopTime="10000");
sim_in = setBlockParameter(sim_in, model_name+"/Curvilinear Speed", "constant", "1");
sim_in = setBlockParameter(sim_in, model_name+"/Curvilinear Speed", "constant_unit", "ft/s");  %!validation-target
%[text] Specify -3 % slope. Use the "linear" option for the interpolation.
% Horizontal distance for vertical profile
sim_in = setBlockParameter(sim_in, block_path, "x_vector", sg([ -1 0 1 ]));
sim_in = setBlockParameter(sim_in, block_path, "x_vector_unit", "ft");

% Road grade profile (percent) ... !validation-target
sim_in = setBlockParameter(sim_in, block_path, "grade_vector", sg([ -3 -3 -3 ]));  %!validation-target

% Profile interpolation method ... !validation-target
sim_in = setBlockParameter(sim_in, block_path, "profile_interp_method", "simscape.enum.interpolation.linear");
%[text] Specify non-zero initial position and elevation. Use "ft" for the unit of length.
% Initial horizontal position
sim_in = setBlockParameter(sim_in, block_path, "initial_position", "2000");  %!validation-target
sim_in = setBlockParameter(sim_in, block_path, "initial_position_unit", "ft");  %!validation-target

% Elevation at initial horizontal position
sim_in = setBlockParameter(sim_in, block_path, "initial_elevation", "100");  %!validation-target
sim_in = setBlockParameter(sim_in, block_path, "initial_elevation_unit", "ft");  %!validation-target
%[text] 
sim_out = sim(sim_in);

result = extractTimetable(sim_out.logsout);

varnames = [
"Curvilinear speed"
"Grade percent"
"Incline angle"
"Elevation"
"Horizontal position"
];

for k = 1 : numel(varnames) %[output:group:7d9db72f]
  bevutil1.SignalUtil.plotTimedData(TimedData=result, SignalName=varnames(k), FigureHeight=150); %[output:51d32380] %[output:5d32bbf4] %[output:3150c359] %[output:09ce5016] %[output:56408894]
end  % for %[output:group:7d9db72f]
